  cat("saved figure:", file.path("figures", name), "\n")
}
show_key <- function(x) paste0('"', x, '"')            # quotes make a trailing space visible
wrap_txt <- function(x, w) paste(strwrap(x, width = w), collapse = "\n")
num <- function(x) suppressWarnings(as.numeric(x))       # text to number; "NA" and "" become NA

# ---- Helper: read the lines of a file -------------------------------------------------------------
read_lines_raw <- function(path) readLines(path, encoding = "UTF-8", warn = FALSE)

# ---- Helper: find the header row ------------------------------------------------------------------
# iMotions files put information ABOVE the table: "#INFO" and "#METADATA" blocks (Sensor Data), a
# "#METADATA" block (R metrics), "#Study Name : ..." lines (data quality), a "Segmentation: ..." line
# (annotations). Never trust a fixed row number: the header moves between releases (FACTS Section 2).
# Rule 1: when the file has a line "#DATA", the header is the NEXT line.
# Rule 2: otherwise the header is the first line that starts with the first column name you expect.
find_header <- function(lines, first_col = NULL) {
  first_field <- sub("[,;\t].*$", "", lines)
  i <- which(first_field == "#DATA")
  if (length(i) > 0) return(i[1] + 1)
  j <- which(first_field == first_col)
  if (length(j) == 0) stop("header not found; expected a line that starts with ", first_col)
  j[1]
}

# ---- Helper: which separator does a line use? --------------------------------------------------------
guess_sep <- function(line) {
  n <- c(comma = str_count(line, ","), tab = str_count(line, "\t"), semicolon = str_count(line, ";"))
  names(n)[which.max(n)]
}

# ---- Helper: read the table that starts at the header row ---------------------------------------------
# Everything is read as TEXT first (col_types character): numbers are converted later, on purpose,
# after the keys are checked. trim_ws = FALSE keeps leading and trailing spaces, so that a key such
# as "P07 " is SEEN (readr would trim it silently by default; Excel does not). quote = "" for the
# tab separated survey files, whose headers contain quotation marks.
read_table_at <- function(lines, header_row, delim, quote = "\"") {
  read_delim(I(lines[header_row:length(lines)]), delim = delim, quote = quote,
             col_types = cols(.default = col_character()), trim_ws = FALSE, na = c("", "NA"),
             name_repair = "minimal", progress = FALSE, show_col_types = FALSE)
}

# ---- Helper: standardize a respondent key ----------------------------------------------------------
# str_trim removes spaces at both ends; str_to_upper makes "p07" and "P07" the same. In Excel the
# same step is =UPPER(TRIM(A2)).
std_key <- function(x) str_to_upper(str_trim(x))

# ---- Helper: the cleaning log ------------------------------------------------------------------------
clog <- tibble(log_id = integer(), step = character(), file = character(), recording = character(),
               participant_id = character(), stimulus = character(), problem = character(), action = character(),
               n_rows_affected = integer(), basis = character())
log_add <- function(step, file, recording, participant_id, stimulus, problem, action, n_rows, basis) {
  clog <<- bind_rows(clog, tibble(log_id = nrow(clog) + 1L, step = step, file = file, recording = recording,
                                  participant_id = participant_id, stimulus = stimulus, problem = problem,
                                  action = action, n_rows_affected = as.integer(n_rows), basis = basis))
}

# ---- Helper: pipeline counts (for the QA report and Figure 1) ------------------------------------------
pipe <- tibble(order = integer(), stage = character(), respondents = integer(), rows = integer(), note = character())
pipe_add <- function(stage, respondents, rows, note = "") {
  pipe <<- bind_rows(pipe, tibble(order = nrow(pipe) + 1L, stage = stage, respondents = as.integer(respondents),
                                  rows = as.integer(rows), note = note))
}

# ---- STEP 1. Inventory of the export bundle ------------------------------------------------------------
# Before reading anything, list what arrived: one folder per export family. Look at the size, the first
# lines, and the separator of every file. A file that is much smaller than its neighbors (004_P04.csv)
# or that uses a different separator (the student copy) is a question to answer before analysis.
cat("---- STEP 1. Inventory of the export bundle ----\n")
files <- list.files(ex_dir, recursive = TRUE, full.names = TRUE)
inv <- tibble(path = files) %>%
  mutate(folder = basename(dirname(path)), file = basename(path), kb = round(file.size(path) / 1024, 1),
         lines = map_int(path, ~ length(read_lines_raw(.x))),
         seed = map_chr(path, ~ str_match(read_lines_raw(.x)[1], "seed ([0-9]+)")[, 2]),
         header_line = map2_int(path, file, function(p, f) {
           L <- read_lines_raw(p)
           first <- case_when(str_detect(f, "MERGED_SURVEY") ~ "STUDY", str_detect(f, "SurveyStatistics") ~ "Stimulus Name",
                              str_detect(f, "DataQuality") ~ "Respondent_Name", str_detect(f, "SessionLog") ~ "Participant ID",
                              TRUE ~ "Study Name")
           as.integer(find_header(L, first))
         }),
         separator = map2_chr(path, header_line, ~ guess_sep(read_lines_raw(.x)[.y + 1])))   # judged on the first DATA row
print(as.data.frame(inv %>% select(folder, file, kb, lines, header_line, separator)), row.names = FALSE)
seed_txt <- unique(na.omit(inv$seed))
cat(sprintf("Files: %d in %d folders; simulation seed: %s\n", nrow(inv), n_distinct(inv$folder), paste(seed_txt, collapse = ", ")))
cat("Header row = the line number of the column names (line 1 is the SIMULATED banner, which a real export does not have).\n")
cat("The separator is judged on the first data row: the survey HEADER contains commas inside the question texts.\n\n")

# ---- STEP 2. The session log --------------------------------------------------------------------------------
# The session log is the KEY TABLE of the study: one row per recording, written by the operator. It
# says which participant each iMotions respondent name belongs to and which recording to use. The
# participant ID (P01 to P24) is the key of every output table; the iMotions respondent name is only
# a recording name.
cat("---- STEP 2. Session log: roster and crosswalk ----\n")
L_log <- read_lines_raw(file.path(ex_dir, "08_Session_Log", "SIMULATED_AdStudy_SessionLog.csv"))
slog <- read_table_at(L_log, find_header(L_log, "Participant ID"), ",")
cross <- slog %>% transmute(participant_id = `Participant ID`, recording = `iMotions respondent name`,
                            key = std_key(`iMotions respondent name`), rec_no = as.integer(Recording),
                            use = `Use recording` == "Yes", session_date = `Session date`, order_log = `Order (typed in Group)`,
                            shimmer = `Shimmer unit`, calibration = `Aurora calibration`, notes = Notes)
roster <- sort(unique(cross$participant_id))
cat(sprintf("Session log rows (recordings): %d; participants: %d (%s to %s)\n", nrow(cross), length(roster), roster[1], tail(roster, 1)))
stopifnot(!any(duplicated(cross$key)))      # every recording name appears once
cat("Participants with more than one recording:\n")
print(as.data.frame(cross %>% group_by(participant_id) %>% filter(n() > 1) %>% select(participant_id, recording, rec_no, use, notes)),
      row.names = FALSE)
cat("Recordings marked Use recording = No:", paste(cross$recording[!cross$use], collapse = ", "), "\n\n")

# ---- STEP 3. The R metrics exports ---------------------------------------------------------------------------
# GSR Peak Metrics, FEA Metrics, and the AOI metrics are R PROCESSING exports. They share the columns
# Study Name, Respondent Name, Gender, Age, Group, Type, Label, Start (ms), Duration (ms), Parent
# Stimulus, then the metrics (FACTS Section 4). Above the header sits a #METADATA block that ends with
# "#DATA". One row per respondent and Type and Label: Type "Stimulus" rows are the slides, Type
# "Annotation" rows are the EndCard annotation inside each ad.
cat("---- STEP 3. R metrics exports ----\n")
read_metrics <- function(rel) {
  L <- read_lines_raw(file.path(ex_dir, rel))
  h <- find_header(L)
  d <- read_table_at(L, h, ",")
  cat(sprintf("%s: header on line %d, %d rows, %d columns\n", rel, h, nrow(d), ncol(d)))
  d
}
