fea_raw  <- read_metrics("03_FEA_Metrics/FEAMetrics.csv")
aoi_raw  <- read_metrics("02_AOI_Metrics/IndividualAOIMetrics.csv")
aoig_raw <- read_metrics("02_AOI_Metrics/AggregatedAOIMetrics.csv")
