# ---- STEP 6. Audit the raw respondent keys ----------------------------------------------------------------------
# The same person is called by a different COLUMN NAME in each export family (Respondent Name,
# RESPONDENT, Respondent_Name) and sometimes by a different SPELLING. Here every raw spelling is compared,
# character for character, with the recording names in the session log.
cat("---- STEP 6. Raw respondent keys ----\n")
key_cols <- tribble(
  ~file,                                ~column,           ~values,
  "GSRPeakMetrics.csv",                 "Respondent Name", gsr_raw$`Respondent Name`,
  "FEAMetrics.csv",                     "Respondent Name", fea_raw$`Respondent Name`,
  "IndividualAOIMetrics.csv",           "Respondent Name", aoi_raw$`Respondent Name`,
  "MERGED_SURVEY_RESPONSE_MATRIX.txt",  "RESPONDENT",      sv_raw$RESPONDENT,
  "_DataQuality.txt",                   "Respondent_Name", dq_raw$Respondent_Name,
  "Individual Annotation Data.csv",     "Respondent Name", an_raw$`Respondent Name`)
audit <- key_cols %>% mutate(distinct = map(values, ~ unique(.x))) %>% select(-values) %>% unnest(distinct) %>%
  rename(raw = distinct) %>% mutate(exact_match = raw %in% cross$recording, std = std_key(raw),
                                    std_match = std %in% cross$key)
audit_sum <- audit %>% group_by(file, column) %>%
  summarize(distinct_names = n(), exact_matches = sum(exact_match),
            not_matching = if (any(!exact_match)) paste(show_key(raw[!exact_match]), collapse = " ") else "(none)", .groups = "drop")
print(as.data.frame(audit_sum), row.names = FALSE)
cat("Characters of the problem keys (utf8ToInt shows the hidden space as 32):\n")
for (k in unique(audit$raw[!audit$exact_match])) cat(sprintf("  %-8s -> %s\n", show_key(k), paste(utf8ToInt(k), collapse = " ")))
n_raw_fail <- dq_raw %>% filter(!Respondent_Name %in% cross$recording) %>% nrow()
cat(sprintf("A join on the RAW keys would lose %d data quality rows and %d survey row(s).\n\n", n_raw_fail,
            sum(!sv_raw$RESPONDENT %in% cross$recording)))

# ---- STEP 7. Standardize the keys and map recordings to participants --------------------------------------------
# (1) key = UPPER(TRIM(raw)); (2) look the key up in the session log to find the participant and whether
# the recording is used; (3) drop the recordings marked No. After this step every table has one key
# column, participant_id, with the same 24 values.
cat("---- STEP 7. Standardized keys, crosswalk, aborted recording dropped ----\n")
map_keys <- function(d, col, fname) {
  d <- d %>% mutate(raw_key = .data[[col]], key = std_key(.data[[col]])) %>%
    left_join(cross %>% select(key, participant_id, recording, use), by = "key")
  if (any(is.na(d$participant_id))) stop(fname, ": keys without a match in the session log: ",
                                         paste(unique(d$raw_key[is.na(d$participant_id)]), collapse = ", "))
  changed <- d %>% filter(raw_key != recording) %>% distinct(raw_key, recording, participant_id)
  for (i in seq_len(nrow(changed))) {
    n_aff <- sum(d$raw_key == changed$raw_key[i])
    prob <- if (str_trim(changed$raw_key[i]) != changed$raw_key[i]) "Respondent name with a trailing space" else
      "Respondent name in lower case"
    log_add("7", fname, changed$recording[i], changed$participant_id[i], "all", paste0(prob, ": ", show_key(changed$raw_key[i])),
            paste0("Standardized with UPPER(TRIM()) to ", show_key(changed$recording[i])), n_aff,
            "Key rule UPPER(TRIM()); the standardized key matches the session log")
  }
  d
}
gsr_k  <- map_keys(gsr_raw, "Respondent Name", "04_GSR_Metrics/GSRPeakMetrics.csv")
fea_k  <- map_keys(fea_raw, "Respondent Name", "03_FEA_Metrics/FEAMetrics.csv")
