drop_report <- function(d, fname) {
  n_drop <- sum(!d$use)
  if (n_drop > 0) log_add("7", fname, paste(unique(d$recording[!d$use]), collapse = ", "), paste(unique(d$participant_id[!d$use]), collapse = ", "),
                          paste(unique(if ("Label" %in% names(d)) d$Label[!d$use] else if ("Stim_Name" %in% names(d)) d$Stim_Name[!d$use] else "all"), collapse = ", "),
                          "Aborted first recording (Aurora calibration failed; stopped 23 s into Baseline)",
                          "Rows dropped", n_drop, "Rule R1; session log Use recording = No")
  cat(sprintf("  %-46s rows before %4d, dropped %d%s, after %4d\n", fname, nrow(d), n_drop,
              if (n_drop > 0) paste0(" (recording ", paste(unique(d$recording[!d$use]), collapse = ", "), ")") else
                " (the aborted recording never reached these stimuli)", nrow(d) - n_drop))
  d %>% filter(use)
}
cat("Rows dropped by rule R1 (the aborted recording 'P04'):\n")
gsr_k <- drop_report(gsr_k, "04_GSR_Metrics/GSRPeakMetrics.csv")
fea_k <- drop_report(fea_k, "03_FEA_Metrics/FEAMetrics.csv")
aoi_k <- drop_report(aoi_k, "02_AOI_Metrics/IndividualAOIMetrics.csv")
sv_k  <- drop_report(sv_k, "05_Survey/MERGED_SURVEY_RESPONSE_MATRIX.txt")
dq_k  <- drop_report(dq_k, "06_Data_Quality/SIMULATED Multimodal Ad Study_DataQuality.txt")
an_k  <- drop_report(an_k, "07_Annotations/Individual Annotation Data.csv")
log_add("7", "all exports", "P04_rerun", "P04", "all", "Rerun saved under another respondent name (P04_rerun)",
        "Mapped to participant P04 through the session log", sum(gsr_k$recording == "P04_rerun") + sum(fea_k$recording == "P04_rerun") +
          sum(aoi_k$recording == "P04_rerun") + sum(sv_k$recording == "P04_rerun") + sum(dq_k$recording == "P04_rerun") +
          sum(an_k$recording == "P04_rerun"), "Session log: use recording 2 as P04")
pipe_add("3 Aborted recording dropped (rule R1)", n_distinct(gsr_k$participant_id), nrow(gsr_k), "P04 recording 1 removed")
for (nm in c("gsr_k", "fea_k", "aoi_k", "sv_k", "dq_k", "an_k")) {
  ids <- unique(get(nm)$participant_id)
  none_if <- function(x) if (length(x) == 0) "none" else paste(x, collapse = ", ")
  cat(sprintf("  %-6s participants: %d; roster participants missing here: %s; codes here that are not in the roster: %s\n", nm, length(ids),
              none_if(setdiff(roster, ids)), none_if(setdiff(ids, roster))))
  stopifnot(setequal(ids, roster))
}
