            paste(names(table(paste(gsr_s$type, gsr_s$stimulus))), table(paste(gsr_s$type, gsr_s$stimulus)), sep = " = ", collapse = ", ")))
gsr_st <- gsr_s %>% filter(type == "Stimulus", stimulus %in% STIMS)
fea_st <- fea_s %>% filter(type == "Stimulus", stimulus %in% STIMS)
