         "Instructions, Questionnaire, and EndCard rows set aside")
dup_check <- function(d, keys, nm) {
  n_dup <- d %>% count(across(all_of(keys))) %>% filter(n > 1) %>% nrow()
  cat(sprintf("  %-34s rows %4d; duplicated (%s): %d\n", nm, nrow(d), paste(keys, collapse = " + "), n_dup))
  stopifnot(n_dup == 0)
}
