dup_check(fea_st, c("participant_id", "stimulus", "Expression"), "FEA (Stimulus rows)")
dup_check(aoi_s, c("participant_id", "stimulus", "AOI Name"), "AOI individual")
dup_check(dq_st, c("participant_id", "stimulus"), "Data quality")
dup_check(sv_k, c("participant_id"), "Survey")
