# ---- STEP 9. Respondent details ---------------------------------------------------------------------------------------
# Gender, Age, and Group are typed into RESPONDENT DETAILS by the operator and copied into every export.
# iMotions fills in Gender OTHER, Age 0, and Group Default when the operator types nothing (Data
# Collection Overview screenshot). Age 0 is impossible here, so it is a missing value, not an age. The
# ad order can be recovered from the data themselves: Ad_A came first when its Start (ms) is smaller.
cat("---- STEP 9. Respondent details: Gender, Age, Group, order of the ads ----\n")
details <- gsr_st %>% distinct(participant_id, Gender, Age, Group)
stopifnot(nrow(details) == length(roster))
details_sv <- sv_k %>% transmute(participant_id, Gender_sv = GENDER, Age_sv = AGE, Group_sv = GROUP)
details_chk <- details %>% left_join(details_sv, by = "participant_id")
cat(sprintf("Gender, Age, Group identical in the GSR export and the survey export: %s\n",
            all(details_chk$Gender == details_chk$Gender_sv & details_chk$Age == details_chk$Age_sv & details_chk$Group == details_chk$Group_sv)))
order_data <- gsr_st %>% filter(stimulus %in% ADS) %>% select(participant_id, stimulus, start = `Start (ms)`) %>%
  mutate(start = num(start)) %>% pivot_wider(names_from = stimulus, values_from = start) %>%
  transmute(participant_id, order_from_data = if_else(Ad_A < Ad_B, "AB", "BA"))
details <- details %>% left_join(order_data, by = "participant_id") %>%
  left_join(cross %>% filter(use) %>% select(participant_id, order_log), by = "participant_id") %>%
  mutate(age = num(Age), defaults = Gender == "OTHER" & age == 0 & Group == "Default")
cat("Respondents whose details are the iMotions defaults:\n")
print(as.data.frame(details %>% filter(defaults) %>% select(participant_id, Gender, Age, Group, order_from_data, order_log)), row.names = FALSE)
n_order_ok <- sum(details$Group == details$order_from_data)
cat(sprintf("Group equals the order found in the data for %d of %d participants; the session log order equals it for %d of %d.\n",
            n_order_ok, nrow(details), sum(details$order_log == details$order_from_data), nrow(details)))
details <- details %>%
  mutate(gender = if_else(defaults, NA_character_, str_to_title(Gender)),
         age = if_else(defaults | age == 0, NA_real_, age),
         order = order_from_data)
for (p in details$participant_id[details$defaults]) {
  log_add("9", "all exports", p, p, "all", "Respondent details left at the iMotions defaults (Gender OTHER, Age 0, Group Default)",
          "Gender and age set to missing (NA); order recovered from Start (ms) of Ad_A and Ad_B (agrees with the session log)", 1,
          "Range check: Age 0 is impossible; Group must be AB or BA")
}
cat(sprintf("After cleaning: age M = %.2f, SD = %.2f, range %d to %d (n = %d, %d missing); gender: %s\n\n",
            mean(details$age, na.rm = TRUE), sd(details$age, na.rm = TRUE), min(details$age, na.rm = TRUE), max(details$age, na.rm = TRUE),
            sum(!is.na(details$age)), sum(is.na(details$age)),
            paste(names(table(details$gender, useNA = "ifany")), table(details$gender, useNA = "ifany"), sep = " = ", collapse = ", ")))

# ---- STEP 10. Survey: LABELID_ and LABELVALUE_ pairs to a tidy table ----------------------------------------------------
# Each header has the form  LABELVALUE_Questionnaire_Liking_A,Question1 "How much did you like ...".
# pivot_longer splits the header into four parts with one regular expression: the part (LABELID or
# LABELVALUE), the slide (Questionnaire; it has no underscore, so the first underscore after the slide
# ends it), the Question ID, and the question text. pivot_wider then puts LABELID and LABELVALUE side by
# side: one row per participant and question, a tidy table (Wickham, 2014).
cat("---- STEP 10. Survey: reshape, score, Cronbach's alpha ----\n")
sv_long <- sv_k %>% select(participant_id, starts_with("LABEL")) %>%
  pivot_longer(-participant_id, names_to = c("part", "slide", "question_id", "question_text"),
               names_pattern = '^(LABELID|LABELVALUE)_([^_]+)_([^,]+),Question1 "(.*)"$', values_to = "value") %>%
  pivot_wider(names_from = part, values_from = value) %>%
  mutate(value = as.integer(LABELVALUE), label_no = as.integer(str_remove(LABELID, "^Label")))
cat(sprintf("Tidy survey: %d rows = %d participants x %d questions; questions: %s\n", nrow(sv_long), n_distinct(sv_long$participant_id),
            n_distinct(sv_long$question_id), paste(unique(sv_long$question_id), collapse = ", ")))
cat(sprintf("Check: LABELID number equals LABELVALUE in %d of %d answers; missing answers: %d\n",
            sum(sv_long$label_no == sv_long$value), nrow(sv_long), sum(is.na(sv_long$value))))
stopifnot(all(sv_long$label_no == sv_long$value))
# Check the raw item means against SurveyStatistics.txt (computed by iMotions over the same 24 people)
st_chk <- sv_long %>% group_by(question_id) %>% summarize(avg = mean(value), sd = sd(value), n = n(), .groups = "drop") %>%
  inner_join(st_raw %>% transmute(question_id = `Question ID`, avg_st = num(Average), sd_st = num(StdDev), n_st = num(Count)), by = "question_id")
cat(sprintf("Raw item means and SDs agree with SurveyStatistics.txt at two decimals: %s (largest gap %.4f)\n",
            all(abs(st_chk$avg - st_chk$avg_st) < 0.006 & abs(st_chk$sd - st_chk$sd_st) < 0.006 & st_chk$n == st_chk$n_st),
            max(abs(st_chk$avg - st_chk$avg_st))))
sv_w <- sv_long %>% select(participant_id, question_id, value) %>% pivot_wider(names_from = question_id, values_from = value)
# Scoring 1: the recall items are multiple choice. The export holds the CHOSEN LABEL (1 to 5), not
# "correct" or "wrong". Correct = 1 (yes) when the label is the advertised brand, else 0 (no).
cat("Recall answers as exported (label value counts):\n")
print(table(Recall_A = sv_w$Recall_A)); print(table(Recall_B = sv_w$Recall_B))
sv_w <- sv_w %>% mutate(recall_ad_a = as.integer(Recall_A == CORRECT["Ad_A"]), recall_ad_b = as.integer(Recall_B == CORRECT["Ad_B"]))
log_add("10", "05_Survey/MERGED_SURVEY_RESPONSE_MATRIX.txt", "all", "all", "Ad_A, Ad_B",
        "Recall items exported as the chosen label (1 to 5), not as correct or wrong",
        "Scored against the answer key: Recall_A correct = Label1 (ALTAVO), Recall_B correct = Label2 (BRENLOW); 1 = yes, 0 = no",
        2 * nrow(sv_w), "Codebook (answer key written before collection)")
cat(sprintf("Brand recalled correctly: Ad_A %d of %d, Ad_B %d of %d\n", sum(sv_w$recall_ad_a), nrow(sv_w), sum(sv_w$recall_ad_b), nrow(sv_w)))
# Scoring 2: the reverse worded item. ATT_3R ("... are a waste of money") runs the other way; on a 1 to 7
# scale the recoded value is 8 minus the answer (7 -> 1, 1 -> 7, 4 -> 4).
cronbach_alpha <- function(items) {
  items <- as.matrix(items)
  k <- ncol(items)
  k / (k - 1) * (1 - sum(apply(items, 2, var)) / var(rowSums(items)))
}
sv_w <- sv_w %>% mutate(att_3_recoded = 8L - ATT_3R)
cat(sprintf("Correlation of ATT_3R with ATT_1 before recoding: r = %.2f; after: r = %.2f\n", cor(sv_w$ATT_1, sv_w$ATT_3R),
            cor(sv_w$ATT_1, sv_w$att_3_recoded)))
alpha_wrong <- cronbach_alpha(sv_w %>% select(ATT_1, ATT_2, ATT_3R))
alpha_right <- cronbach_alpha(sv_w %>% select(ATT_1, ATT_2, att_3_recoded))
# the same alpha, step by step, so it can be checked with a calculator
iv <- apply(as.matrix(sv_w %>% select(ATT_1, ATT_2, att_3_recoded)), 2, var)
tv <- var(rowSums(sv_w %>% select(ATT_1, ATT_2, att_3_recoded)))
cat(sprintf("Cronbach's alpha = k / (k - 1) x (1 - sum of item variances / variance of the sum), k = 3:\n"))
cat(sprintf("  item variances %.4f, %.4f, %.4f (sum %.4f); variance of the sum %.4f; alpha = 1.5 x (1 - %.4f / %.4f) = %.3f\n",
            iv[1], iv[2], iv[3], sum(iv), tv, sum(iv), tv, alpha_right))
cat(sprintf("Alpha WITHOUT recoding ATT_3R = %.3f (the mistake); WITH recoding = %.3f (n = %d)\n", alpha_wrong, alpha_right, nrow(sv_w)))
sv_w <- sv_w %>% mutate(attitude = (ATT_1 + ATT_2 + att_3_recoded) / 3)
cat(sprintf("Attitude score (mean of the three items, 1 to 7): M = %.2f, SD = %.2f; purchase intention: M = %.2f, SD = %.2f\n\n",
            mean(sv_w$attitude), sd(sv_w$attitude), mean(sv_w$PI), sd(sv_w$PI)))
log_add("10", "05_Survey/MERGED_SURVEY_RESPONSE_MATRIX.txt", "all", "all", "Questionnaire", "ATT_3R is reverse worded",
        sprintf("Recoded as 8 - ATT_3R; attitude = mean of ATT_1, ATT_2, recoded ATT_3R (alpha %.2f; %.2f without recoding)", alpha_right, alpha_wrong),
        nrow(sv_w), "Codebook (scale scoring written before collection)")

# ---- STEP 11. GSR: signal check (rule R3) ---------------------------------------------------------------------------------
# Signal Duration (ms) is the time with GSR signal, without gaps longer than 4 seconds. When the Shimmer
# loses its connection, Peaks Per Minute is computed over the little signal left and is not
# trustworthy. Rule R3 marks a stimulus as missing for GSR analyses when less than 80 percent remains.
cat("---- STEP 11. GSR signal check (rule R3) ----\n")
gsr_t <- gsr_st %>% transmute(participant_id, stimulus, gsr_start_ms = num(`Start (ms)`), duration_ms = num(`Duration (ms)`),
                              signal_ms = num(`Signal Duration (ms)`), gsr_peak_count_raw = num(`Peak Count`),
                              gsr_ppm_raw = num(`Peaks Per Minute`), gsr_amp_raw = num(`Average Peak Amplitude (microSiemens)`)) %>%
  mutate(gsr_signal_pct = 100 * signal_ms / duration_ms, gsr_valid = as.integer(signal_ms / duration_ms >= GSR_MIN),
         gsr_peaks_per_min = if_else(gsr_valid == 1, gsr_ppm_raw, NA_real_),
         gsr_peak_count = if_else(gsr_valid == 1, gsr_peak_count_raw, NA_real_),
         gsr_avg_amp_us = if_else(gsr_valid == 1, gsr_amp_raw, NA_real_))
cat("Stimuli with Signal Duration below 100 percent:\n")
print(as.data.frame(gsr_t %>% filter(gsr_signal_pct < 100) %>%
                      transmute(participant_id, stimulus, duration_ms, signal_ms, signal_pct = round(gsr_signal_pct, 1),
                                peaks_per_min_raw = gsr_ppm_raw, valid = gsr_valid)), row.names = FALSE)
for (i in which(gsr_t$gsr_valid == 0)) {
  log_add("11", "04_GSR_Metrics/GSRPeakMetrics.csv", gsr_t$participant_id[i], gsr_t$participant_id[i], gsr_t$stimulus[i],
          sprintf("Shimmer dropout: Signal Duration %d of %d ms (%.1f percent); Peaks Per Minute %.3f computed on %.1f s",
                  as.integer(gsr_t$signal_ms[i]), as.integer(gsr_t$duration_ms[i]), gsr_t$gsr_signal_pct[i], gsr_t$gsr_ppm_raw[i], gsr_t$signal_ms[i] / 1000),
          "GSR values set to missing for this stimulus (GSR analyses only); participant kept in all other analyses", 1,
          "Rule R3; session log note (low battery)")
}
for (i in which(gsr_t$gsr_valid == 1 & gsr_t$gsr_signal_pct < 100)) {
  log_add("11", "04_GSR_Metrics/GSRPeakMetrics.csv", gsr_t$participant_id[i], gsr_t$participant_id[i], gsr_t$stimulus[i],
          sprintf("Bluetooth gap: Signal Duration %.1f percent of Duration", gsr_t$gsr_signal_pct[i]),
          "Kept (80 percent or more); Peaks Per Minute already uses Signal Duration", 0, "Rule R3")
}
for (i in which(gsr_t$gsr_signal_pct < 100)) cat(sprintf("  %s %s: %.1f s of signal in %.1f s (gap or loss %.1f s)\n", gsr_t$participant_id[i],
                                                       gsr_t$stimulus[i], gsr_t$signal_ms[i] / 1000, gsr_t$duration_ms[i] / 1000,
                                                       (gsr_t$duration_ms[i] - gsr_t$signal_ms[i]) / 1000))
cat(sprintf("GSR stimulus values set to missing: %d; kept with a gap: %d\n\n", sum(gsr_t$gsr_valid == 0),
            sum(gsr_t$gsr_valid == 1 & gsr_t$gsr_signal_pct < 100)))

# ---- STEP 12. FEA: one column per expression -------------------------------------------------------------------------------
cat("---- STEP 12. FEA: from long (one row per expression) to one column per expression ----\n")
fea_t <- fea_st %>% transmute(participant_id, stimulus, Expression, pct = num(`Percent of time present`)) %>%
  mutate(var = recode(Expression, "Joy" = "joy_pct", "Engagement" = "engagement_pct", "Brow Furrow" = "browfurrow_pct")) %>%
  select(-Expression) %>% pivot_wider(names_from = var, values_from = pct)
cat(sprintf("FEA rows: %d long -> %d wide (participant x stimulus); columns: %s\n\n", nrow(fea_st), nrow(fea_t),
            paste(names(fea_t), collapse = ", ")))

# ---- STEP 13. AOI metrics ------------------------------------------------------------------------------------------------------
# NA means two different things. TTFF AOI (ms) is NA when the Logo was never fixated: a time that does
# not exist, so it STAYS missing. Fixation count and Gaze Dwell time are NA for the same reason, but a
# person who never looked spent 0 ms there, so those become 0 (and the cleaning log says so). The hit
# (fixated or not) is the variable of H1.
cat("---- STEP 13. AOI metrics: Logo hit, NA versus 0, the aggregated file ----\n")
aoi_t <- aoi_s %>% transmute(participant_id, stimulus, aoi = `AOI Name`, ttff = num(`TTFF AOI (ms)`), fix_count = num(`Fixation count`),
                             ratio = num(`Respondent ratio (%)`), gaze_dwell_ms = num(`Gaze Dwell time (ms)`),
                             gaze_dwell_pct = num(`Gaze Dwell time (%)`), revisits = num(`Revisit count`))
n_na_logo <- aoi_t %>% filter(aoi == "Logo", is.na(ttff)) %>% nrow()
stopifnot(all((aoi_t$ratio == 100) == !is.na(aoi_t$ttff)))
cat(sprintf("Logo rows: %d; never fixated (TTFF NA, Respondent ratio 0): %d. Respondent ratio (%%) = 100 exactly when TTFF is not NA: TRUE\n",
            sum(aoi_t$aoi == "Logo"), n_na_logo))
aoi_w <- aoi_t %>% filter(aoi %in% c("Logo", "Product", "Headline")) %>%
  mutate(fixated = as.integer(!is.na(ttff)), fix_count = replace_na(fix_count, 0), gaze_dwell_ms = replace_na(gaze_dwell_ms, 0),
         gaze_dwell_pct = replace_na(gaze_dwell_pct, 0), revisits = replace_na(revisits, 0)) %>%
  select(participant_id, stimulus, aoi, fixated, ttff, fix_count, gaze_dwell_ms, gaze_dwell_pct, revisits) %>%
  pivot_wider(names_from = aoi, values_from = c(fixated, ttff, fix_count, gaze_dwell_ms, gaze_dwell_pct, revisits), names_glue = "{tolower(aoi)}_{.value}") %>%
  transmute(participant_id, stimulus, logo_fixated = logo_fixated, logo_ttff_ms = logo_ttff, logo_fix_count = logo_fix_count,
            logo_revisits = logo_revisits, logo_gaze_dwell_ms = logo_gaze_dwell_ms, logo_gaze_dwell_pct = logo_gaze_dwell_pct,
            product_gaze_dwell_pct = product_gaze_dwell_pct, headline_gaze_dwell_pct = headline_gaze_dwell_pct)
log_add("13", "02_AOI_Metrics/IndividualAOIMetrics.csv", "all", "all", "Ad_A, Ad_B",
        sprintf("Never fixated or never gazed AOIs have NA in count and dwell columns (Logo: %d of %d rows)", n_na_logo, sum(aoi_t$aoi == "Logo")),
        "Counts and dwell times set to 0; TTFF AOI (ms) kept as NA (no first fixation exists)", n_na_logo,
        "Codebook: missing because it cannot exist versus zero")
agg_chk <- aoi_t %>% group_by(stimulus, aoi) %>% summarize(ratio_all = 100 * mean(!is.na(ttff)), n_all = n(), .groups = "drop") %>%
  inner_join(aoig_raw %>% transmute(stimulus = Label, aoi = `AOI Name`, ratio_export = num(`Respondent ratio (%)`), base = num(`Respondent base`)),
             by = c("stimulus", "aoi"))
cat("Respondent ratio (%) recomputed from the individual file versus the aggregated export (all 24 participants):\n")
print(as.data.frame(agg_chk %>% mutate(ratio_all = round(ratio_all, 1))), row.names = FALSE)
stopifnot(all(abs(agg_chk$ratio_all - agg_chk$ratio_export) < 0.06))
cat("They agree. The aggregated file averages over EVERY respondent in the iMotions analysis, before any exclusion,\n")
cat("so it cannot be used for the analysis sample or for tests (one number per AOI, not one per person).\n\n")

# ---- STEP 14. Three time bases ------------------------------------------------------------------------------------------------
# Sensor Data "Timestamp": ms since the RECORDING started. R metrics "Start (ms)": ms since the start of
# the STUDY (here modeled as the StartSlide event of the first slide). Annotation export "Start Time(ms)":
# ms since the STIMULUS onset. Before comparing times across files, convert them to one clock.
cat("---- STEP 14. Three time bases ----\n")
an_t <- an_s %>% filter(`Marker Name` == "EndCard") %>% transmute(participant_id, stimulus, an_start = num(`Start Time(ms)`),
                                                                   an_end = num(`End Time(ms)`))
cat(sprintf("Annotation export: EndCard Start Time(ms) = %s and End Time(ms) = %s for all %d rows (relative to the ad's onset).\n",
            paste(unique(an_t$an_start), collapse = ", "), paste(unique(an_t$an_end), collapse = ", "), nrow(an_t)))
endcard_r <- gsr_s %>% filter(type == "Annotation", stimulus == "EndCard") %>%
  transmute(participant_id, ad = `Parent Stimulus`, ec_start = num(`Start (ms)`)) %>%
  inner_join(gsr_st %>% filter(stimulus %in% ADS) %>% transmute(participant_id, ad = stimulus, ad_start = num(`Start (ms)`)),
             by = c("participant_id", "ad")) %>% mutate(diff = ec_start - ad_start)
cat(sprintf("R metrics: EndCard Start (ms) minus its ad's Start (ms) = %s ms for all %d annotation rows (study clock).\n",
            paste(unique(endcard_r$diff), collapse = ", "), nrow(endcard_r)))
cat("(The Sensor Data clock is checked in step 15, where the raw files are read.)\n\n")

# ---- STEP 15. Sensor Data (P01 to P06) ------------------------------------------------------------------------------------------
# One file per recording. The file NAME starts with the respondent's position in the study (001, 002,
# ...), not with the participant number: the recording name is read from the #INFO line "#Respondent
# Name". The header row holds "EventSource" four times (one per device); the #METADATA row "#Device"
# says which device each column belongs to, so the duplicated names are rebuilt as
# "EventSource (<device>)", the way the export editor's preview shows them.
cat("---- STEP 15. Sensor Data: raw samples versus the metrics exports ----\n")
sd_files <- sort(list.files(file.path(ex_dir, "01_Sensor_Data"), pattern = "\\.csv$", full.names = TRUE))
read_sensor <- function(path) {
  L <- read_lines_raw(path)
  h <- find_header(L)
  info_name <- str_split(L[str_detect(L, "^#Respondent Name,")], ",")[[1]][2]
  device <- str_split(L[str_detect(L, "^#Device,")], ",")[[1]]
  d <- read_table_at(L, h, ",")
  nm <- names(d)
  nm[nm == "EventSource"] <- paste0("EventSource (", device[nm == "EventSource"], ")")
  names(d) <- nm
  list(file = basename(path), recording = info_name, header_row = h, data = d, n_dup = sum(names(read_table_at(L[1:h], h, ",")) == "EventSource"))
}
sd_list <- map(sd_files, read_sensor)
sd_index <- tibble(file = map_chr(sd_list, "file"), recording = map_chr(sd_list, "recording"), header_row = map_int(sd_list, "header_row"),
                   rows = map_int(sd_list, ~ nrow(.x$data)), eventsource_cols = map_int(sd_list, "n_dup")) %>%
  mutate(key = std_key(recording)) %>% left_join(cross %>% select(key, participant_id, use), by = "key") %>% select(-key)
print(as.data.frame(sd_index), row.names = FALSE)
cat("Names after rebuilding the duplicated headers (file 1):", paste(names(sd_list[[1]]$data)[c(3, 9, 14, 20)], collapse = " | "), "\n")
log_add("15", "01_Sensor_Data/*.csv", "P01 to P06", "P01 to P06", "all", "Header row holds EventSource four times (one per device)",
        "Renamed EventSource (<device>) from the #METADATA #Device row", sum(sd_index$rows), "Export: Sensor Data article (one Eventsource column per device)")
sd_use <- sd_list[sd_index$use]
cat(sprintf("Files used: %d (the file of the aborted recording, %s, is skipped by rule R1).\n",
            length(sd_use), paste(sd_index$file[!sd_index$use], collapse = ", ")))
log_add("15", paste0("01_Sensor_Data/", paste(sd_index$file[!sd_index$use], collapse = ", ")), "P04", "P04", "Baseline",
        "Sensor Data file of the aborted recording (only 23 s of Baseline)", "File not used", sd_index$rows[!sd_index$use],
        "Rule R1; session log Use recording = No")

sensor_summary <- map_dfr(sd_use, function(s) {
  d <- s$data
  et_col <- names(d)[str_detect(names(d), "^EventSource \\(Eyetracker")]
  fe_col <- names(d)[str_detect(names(d), "^EventSource \\(Affectiva")]
  gs_col <- names(d)[str_detect(names(d), "^EventSource \\(Shimmer")]
  ev <- d %>% filter(`EventSource (SlideEvents)` == "1") %>% transmute(stimulus = SourceStimuliName, event = SlideEvent, t = num(Timestamp))
  map_dfr(STIMS, function(st) {
    t0 <- ev$t[ev$stimulus == st & ev$event == "StartMedia"]
    t1 <- ev$t[ev$stimulus == st & ev$event == "EndMedia"]
    w <- d %>% mutate(t = num(Timestamp)) %>% filter(t >= t0, t < t1)
    et <- w %>% filter(.data[[et_col]] == "1")
    fe <- w %>% filter(.data[[fe_col]] == "1")
    gs <- w %>% filter(.data[[gs_col]] == "1")
    ec <- if (st %in% ADS) min(w$t[w$EndCard %in% "1"]) - t0 else NA_real_
    tibble(recording = s$recording, stimulus = st, start_media = t0, end_media = t1, et_rows = nrow(et),
           et_valid_pct = 100 * mean(!is.na(et$ET_GazeLeftx)),
           logo_share_et = if (st %in% ADS) 100 * mean(et$Logo_gazed == "1") else NA_real_,
           logo_share_allrows = if (st %in% ADS) 100 * mean(replace_na(w$Logo_gazed == "1", FALSE)) else NA_real_,
           joy_share = 100 * mean(replace_na(num(fe$Joy) >= 50, FALSE)), fe_rows = nrow(fe),
           gsr_rows = nrow(gs), gsr_expected = round((t1 - t0) / 1000 * 128), endcard_first_ms = ec)
  })
}) %>% mutate(key = std_key(recording)) %>% left_join(cross %>% select(key, participant_id), by = "key") %>% select(-key)

# (a) the clock: Sensor Data StartMedia minus R metrics Start (ms)
clock <- sensor_summary %>% select(participant_id, stimulus, start_media) %>%
  inner_join(gsr_t %>% select(participant_id, stimulus, gsr_start_ms), by = c("participant_id", "stimulus")) %>%
  mutate(offset_ms = start_media - gsr_start_ms)
clock_sum <- clock %>% group_by(participant_id) %>% summarize(offset_min = min(offset_ms), offset_max = max(offset_ms),
                                                              spread_ms = max(offset_ms) - min(offset_ms), .groups = "drop")
cat("(a) Sensor Data StartMedia (recording clock) minus GSR Start (ms) (study clock), per participant:\n")
print(as.data.frame(clock_sum %>% mutate(across(where(is.numeric), ~ round(.x, 1)))), row.names = FALSE)
cat(sprintf("The offset is constant within each participant (largest spread %.1f ms, rounding) and differs between participants\n",
            max(clock_sum$spread_ms)))
cat(sprintf("(%.0f to %.0f ms): the two files count from different zero points. Offset 0 would mean 'start of the study' = recording start.\n",
            min(clock_sum$offset_min), max(clock_sum$offset_max)))
log_add("15", "Sensor Data versus R metrics", "P01 to P06", "P01 to P06", "Baseline, Ad_A, Ad_B",
        sprintf("Two clocks: Timestamp counts from the recording start, Start (ms) from the study start (offset %.0f to %.0f ms)",
                min(clock_sum$offset_min), max(clock_sum$offset_max)),
        "Times compared only after converting to one clock (offset per participant)", nrow(clock), "Export: Sensor Data and R Processed GSR articles")
# (b) the annotation, converted from the stimulus clock to the recording clock
cat("(b) EndCard: first Sensor Data sample with EndCard = 1, in ms after the ad's StartMedia (annotation export says 25000):\n")
ec_chk <- sensor_summary %>% filter(stimulus %in% ADS) %>% select(participant_id, stimulus, start_media, endcard_first_ms) %>%
  mutate(endcard_recording_clock = start_media + 25000)
print(as.data.frame(ec_chk %>% mutate(across(where(is.numeric), ~ round(.x, 1)))), row.names = FALSE)
cat(sprintf("All within one sample of 25000 ms (largest gap %.1f ms): the annotation export counts from the stimulus onset.\n",
            max(abs(ec_chk$endcard_first_ms - 25000))))
log_add("15", "07_Annotations/Individual Annotation Data.csv", "all", "all", "Ad_A, Ad_B",
        "Annotation times count from the stimulus onset (a third clock)",
        "Converted: recording time = StartMedia of the ad + Start Time(ms); confirmed against the EndCard column of Sensor Data",
        nrow(an_t), "Export: Annotations article")
# (c) consistency of the raw samples with the metrics exports
cons <- sensor_summary %>% filter(stimulus %in% ADS) %>%
  left_join(aoi_w %>% select(participant_id, stimulus, logo_gaze_dwell_pct), by = c("participant_id", "stimulus")) %>%
  left_join(fea_t %>% select(participant_id, stimulus, joy_pct), by = c("participant_id", "stimulus")) %>%
  mutate(logo_diff = logo_share_et - logo_gaze_dwell_pct, joy_diff = joy_share - joy_pct)
cat("(c) Raw samples versus the exports (ads; 6 participants):\n")
print(as.data.frame(cons %>% transmute(participant_id, stimulus, et_rows, logo_share_et = round(logo_share_et, 2),
                                       logo_gaze_dwell_pct = round(logo_gaze_dwell_pct, 2), logo_diff = round(logo_diff, 2),
                                       logo_share_allrows = round(logo_share_allrows, 2), joy_share = round(joy_share, 2),
                                       joy_pct = round(joy_pct, 2))), row.names = FALSE)
cat(sprintf("Logo: share of EYE TRACKER rows with Logo_gazed = 1 versus Gaze Dwell time (%%): mean absolute difference %.2f, largest %.2f percentage points;\n",
            mean(abs(cons$logo_diff)), max(abs(cons$logo_diff))))
cat(sprintf("  correlation r = %.3f over %d participant x ad pairs. Small differences are expected: the export drops dwells shorter than 100 ms.\n",
            cor(cons$logo_share_et, cons$logo_gaze_dwell_pct), nrow(cons)))
cat(sprintf("  The WRONG denominator (all rows of every device) gives %.2f percent on average instead of %.2f: count eye tracker rows only.\n",
            mean(cons$logo_share_allrows), mean(cons$logo_share_et)))
cat(sprintf("Joy: share of AFFDEX rows with Joy >= 50 versus Percent of time present: largest difference %.2f percentage points.\n",
            max(abs(cons$joy_diff))))
stopifnot(max(abs(cons$logo_diff)) < 2, max(abs(cons$joy_diff)) < 0.5)
cat("Consistency check passed (Logo within 2 points, Joy within 0.5 points).\n")
gsr_rows_chk <- sensor_summary %>% transmute(participant_id, stimulus, gsr_rows, gsr_expected, pct = round(100 * gsr_rows / gsr_expected, 1)) %>%
  filter(pct < 98)
cat("GSR samples below 98 percent of the expected number (128 per second):\n")
print(as.data.frame(gsr_rows_chk), row.names = FALSE)
cat("This is P05's Shimmer dropout, visible in the raw file too: the GSR rows stop about 8 s into Ad_B.\n\n")

# ---- STEP 16. Data quality and the exclusion rule (R2) ----------------------------------------------------------------------------
cat("---- STEP 16. Data quality and the exclusion rule (R2) ----\n")
dq_t <- dq_st %>% transmute(participant_id, stimulus, et_quality_pct = num(`Eye tracking_Quality`), face_quality_pct = num(`Affectiva AFFDEX_Quality`),
                            gsr_quality_pct = num(`Shimmer GSR_Quality`))
rule <- dq_t %>% filter(stimulus %in% ADS) %>% group_by(participant_id) %>%
  summarize(et_min_ads = min(et_quality_pct), face_min_ads = min(face_quality_pct), .groups = "drop") %>%
  mutate(fail_et = et_min_ads < ET_MIN, fail_face = face_min_ads < FACE_MIN,
         include = as.integer(!(fail_et | fail_face)),
         exclusion_reason = case_when(fail_et & fail_face ~ "eye tracking and face quality",
                                      fail_et ~ sprintf("eye tracking quality below %d percent on an ad", ET_MIN),
                                      fail_face ~ sprintf("face found below %d percent on an ad", FACE_MIN), TRUE ~ ""))
cat(sprintf("Lowest quality on the two ads, all participants: eye tracking %d to %d percent, face %d to %d percent\n",
            as.integer(min(rule$et_min_ads)), as.integer(max(rule$et_min_ads)), as.integer(min(rule$face_min_ads)), as.integer(max(rule$face_min_ads))))
cat("Participants who fail rule R2:\n")
print(as.data.frame(rule %>% filter(include == 0)), row.names = FALSE)
cat("Closest to a threshold without failing:\n")
print(as.data.frame(rule %>% filter(include == 1) %>% arrange(et_min_ads - ET_MIN) %>% head(2)), row.names = FALSE)
for (i in which(rule$include == 0)) {
  log_add("16", "06_Data_Quality/SIMULATED Multimodal Ad Study_DataQuality.txt", rule$participant_id[i], rule$participant_id[i], "Ad_A, Ad_B",
          sprintf("Data quality on the ads: eye tracking minimum %d percent, face minimum %d percent", as.integer(rule$et_min_ads[i]),
                  as.integer(rule$face_min_ads[i])),
          paste0("Excluded from all analyses (", rule$exclusion_reason[i], ")"), 3, "Rule R2, written before collection")
}
# What happens with the RAW keys: the participant whose key does not match gets NA quality, and a filter
# on quality drops NA rows WITHOUT a warning.
naive <- dq_raw %>% filter(Stim_Name %in% ADS) %>% group_by(Respondent_Name) %>%
  summarize(et = min(num(`Eye tracking_Quality`)), face = min(num(`Affectiva AFFDEX_Quality`)), .groups = "drop")
naive_join <- tibble(participant_id = roster) %>% left_join(naive, by = c("participant_id" = "Respondent_Name"))
naive_kept <- naive_join %>% filter(et >= ET_MIN, face >= FACE_MIN)
cat(sprintf("Lesson: joined on the RAW keys, %d participants get NA quality (%s: \"P07 \" has a space, P04's ads are under P04_rerun).\n",
            sum(is.na(naive_join$et)), paste(naive_join$participant_id[is.na(naive_join$et)], collapse = " and ")))
cat(sprintf("filter(et >= %d, face >= %d) drops NA rows WITHOUT a warning: it would keep %d participants instead of %d.\n",
            ET_MIN, FACE_MIN, nrow(naive_kept), sum(rule$include)))
n_incl <- sum(rule$include)
cat(sprintf("Analysis sample: %d of %d participants.\n\n", n_incl, nrow(rule)))

# ---- STEP 17. Join everything --------------------------------------------------------------------------------------------------------
# The spine is the full grid participant x stimulus (24 x 3 = 72 rows). Every other table is joined onto
# it with left_join by the SAME two keys, and the row count is checked after each join: a join that adds
# rows has found a duplicate key; a join that leaves NA where data should be has found a key mismatch.
cat("---- STEP 17. Join: long table (participant x stimulus) and wide table (participant) ----\n")
spine <- expand_grid(participant_id = roster, stimulus = STIMS)
sv_ad <- sv_w %>% transmute(participant_id, Ad_A = Liking_A, Ad_B = Liking_B) %>% pivot_longer(-participant_id, names_to = "stimulus", values_to = "liking") %>%
  left_join(sv_w %>% transmute(participant_id, Ad_A = recall_ad_a, Ad_B = recall_ad_b) %>%
              pivot_longer(-participant_id, names_to = "stimulus", values_to = "recall_correct"), by = c("participant_id", "stimulus"))
steps_join <- list(
  list("respondent details", details %>% select(participant_id, order, gender, age), "participant_id"),
  list("exclusion rule", rule %>% select(participant_id, include, exclusion_reason), "participant_id"),
  list("data quality", dq_t, c("participant_id", "stimulus")),
  list("GSR", gsr_t %>% select(participant_id, stimulus, gsr_signal_pct, gsr_valid, gsr_peaks_per_min, gsr_peak_count, gsr_avg_amp_us),
       c("participant_id", "stimulus")),
  list("FEA", fea_t, c("participant_id", "stimulus")),
  list("AOI", aoi_w, c("participant_id", "stimulus")),
  list("survey (ad items)", sv_ad, c("participant_id", "stimulus")))
long <- spine
for (j in steps_join) {
  n0 <- nrow(long)
  long <- left_join(long, j[[2]], by = j[[3]])
  cat(sprintf("  + %-18s rows %d -> %d\n", j[[1]], n0, nrow(long)))
  stopifnot(nrow(long) == n0)
}
long <- long %>% mutate(ad_position = case_when(stimulus == "Baseline" ~ NA_integer_,
                                                (order == "AB" & stimulus == "Ad_A") | (order == "BA" & stimulus == "Ad_B") ~ 1L, TRUE ~ 2L)) %>%
  relocate(ad_position, .after = stimulus) %>% arrange(participant_id, factor(stimulus, levels = STIMS))
pipe_add("5 Joined with FEA, AOI, survey, data quality", n_distinct(long$participant_id), nrow(long), "no rows gained or lost")
miss_ad <- long %>% filter(stimulus %in% ADS) %>% summarize(across(c(liking, recall_correct, logo_fixated, joy_pct, et_quality_pct), ~ sum(is.na(.x))))
cat("Missing values in the ad rows after the joins (should be 0):", paste(names(miss_ad), miss_ad, sep = " = ", collapse = ", "), "\n")
stopifnot(all(miss_ad == 0))
n_long_incl <- sum(long$include == 1)
pipe_add("6 Exclusion rule R2 applied (include = 1)", n_distinct(long$participant_id[long$include == 1]), n_long_incl, "P18 and P21 excluded")
pipe_add("7 GSR analyses: valid GSR only (rule R3)", n_distinct(long$participant_id[long$include == 1 & long$gsr_valid == 1]),
         sum(long$include == 1 & long$gsr_valid == 1), "P05 Ad_B missing for GSR")
# The wide table: one row per participant
wide <- details %>% select(participant_id, order, gender, age) %>%
  left_join(cross %>% filter(use) %>% select(participant_id, recording), by = "participant_id") %>%
  left_join(rule %>% select(participant_id, include, exclusion_reason), by = "participant_id") %>%
  left_join(sv_w %>% transmute(participant_id, att_1 = ATT_1, att_2 = ATT_2, att_3r_raw = ATT_3R, att_3_recoded, attitude,
                               purchase_intention = PI), by = "participant_id") %>%
  left_join(long %>% select(participant_id, stimulus, liking, recall_correct, logo_fixated, joy_pct, gsr_peaks_per_min, gsr_valid,
                            et_quality_pct, face_quality_pct) %>%
              pivot_wider(names_from = stimulus, values_from = c(liking, recall_correct, logo_fixated, joy_pct, gsr_peaks_per_min, gsr_valid,
                                                                 et_quality_pct, face_quality_pct), names_glue = "{.value}_{tolower(stimulus)}"),
            by = "participant_id") %>%
  select(-any_of(c("liking_baseline", "recall_correct_baseline", "logo_fixated_baseline"))) %>%
  relocate(recording, .after = participant_id)
cat(sprintf("Long table: %d rows x %d columns; wide table: %d rows x %d columns\n\n", nrow(long), ncol(long), nrow(wide), ncol(wide)))

