  "wide", "attitude", "Attitude toward reusable water bottles: mean of att_1, att_2, att_3_recoded", SVF, "ATT_1, ATT_2, ATT_3R", "number", "scale points", 1, 7, "never missing",
  "wide", "purchase_intention", "Purchase intention, next three months (1 to 7)", SVF, "LABELVALUE_Questionnaire_PI", "integer", "scale points", 1, 7, "never missing")
wide_map <- c(liking_ad_a = "liking", liking_ad_b = "liking", recall_correct_ad_a = "recall_correct", recall_correct_ad_b = "recall_correct",
              logo_fixated_ad_a = "logo_fixated", logo_fixated_ad_b = "logo_fixated", joy_pct_baseline = "joy_pct", joy_pct_ad_a = "joy_pct",
              joy_pct_ad_b = "joy_pct", gsr_peaks_per_min_baseline = "gsr_peaks_per_min", gsr_peaks_per_min_ad_a = "gsr_peaks_per_min",
              gsr_peaks_per_min_ad_b = "gsr_peaks_per_min", gsr_valid_baseline = "gsr_valid", gsr_valid_ad_a = "gsr_valid", gsr_valid_ad_b = "gsr_valid",
              et_quality_pct_baseline = "et_quality_pct", et_quality_pct_ad_a = "et_quality_pct", et_quality_pct_ad_b = "et_quality_pct",
              face_quality_pct_baseline = "face_quality_pct", face_quality_pct_ad_a = "face_quality_pct", face_quality_pct_ad_b = "face_quality_pct")
cb_wide <- map_dfr(names(wide_map), function(v) {
  base <- cb %>% filter(variable == wide_map[[v]])
  st <- c(baseline = "Baseline", ad_a = "Ad_A", ad_b = "Ad_B")[str_extract(v, "(baseline|ad_a|ad_b)$")]
  base %>% mutate(dataset = "wide", variable = v, label = paste0(label, " (", st, ")"),
                  missing_code = str_replace(missing_code, "NA = Baseline row", "never missing"))
})
cb_all <- bind_rows(cb, cb_wide) %>%
  mutate(allowed_range = case_when(!is.na(lo) ~ paste(lo, "to", hi), type == "text" ~ "text", TRUE ~ ""))
stopifnot(all(names(long) %in% cb_all$variable), all(names(wide) %in% cb_all$variable))
codebook <- cb_all %>% transmute(variable, label, source_file, source_column, type, units, allowed_range, missing_code, dataset)
# QA report: ranges, duplicates, missing values
qa_range <- function(d, nm) {
  map_dfr(names(d), function(v) {
    x <- d[[v]]
    r <- cb_all %>% filter(variable == v) %>% slice(1)
    if (!is.numeric(x)) return(tibble(table = nm, variable = v, n = length(x), missing = sum(is.na(x) | x == ""), min = NA_real_, max = NA_real_,
                                      allowed = r$allowed_range, out_of_range = 0L))
    tibble(table = nm, variable = v, n = length(x), missing = sum(is.na(x)), min = suppressWarnings(min(x, na.rm = TRUE)),
           max = suppressWarnings(max(x, na.rm = TRUE)), allowed = r$allowed_range,
           out_of_range = sum(!is.na(x) & (x < r$lo | x > r$hi)))
  })
}
qa <- bind_rows(qa_range(long, "long"), qa_range(wide, "wide"))
stopifnot(sum(qa$out_of_range) == 0)
dups_long <- long %>% count(participant_id, stimulus) %>% filter(n > 1) %>% nrow()
dups_wide <- wide %>% count(participant_id) %>% filter(n > 1) %>% nrow()
cat(sprintf("QA: values outside the codebook range: %d; duplicated keys: long %d, wide %d\n", sum(qa$out_of_range), dups_long, dups_wide))
cat("Variables with missing values (and why, from the codebook):\n")
print(as.data.frame(qa %>% filter(missing > 0) %>% left_join(codebook %>% distinct(variable, .keep_all = TRUE) %>% select(variable, missing_code), by = "variable") %>%
                      select(table, variable, n, missing, missing_code)), row.names = FALSE)

banner <- function(what) sprintf("# SIMULATED DATA for teaching (seed %s). %s Made by prepare_data.R from the export bundle in exports/. No real person was recorded.",
                                 seed_txt, what)
write_with_banner <- function(d, file, what) {
  writeLines(banner(what), file)
  write_csv(d, file, append = TRUE, col_names = TRUE, na = "NA")
  cat(sprintf("wrote %s (%d rows, %d columns)\n", file, nrow(d), ncol(d)))
}
long_out <- long %>% mutate(across(where(is.double), ~ round(.x, 4)))
wide_out <- wide %>% mutate(across(where(is.double), ~ round(.x, 4)))
write_with_banner(long_out, "analysis_ready_long.csv", "One row per participant and stimulus (Baseline, Ad_A, Ad_B); include = 1 marks the analysis sample.")
write_with_banner(wide_out, "analysis_ready_wide.csv", "One row per participant.")
write_with_banner(codebook, "codebook.csv", "Codebook of analysis_ready_long.csv and analysis_ready_wide.csv.")
write_with_banner(clog, "cleaning_log.csv", "Every cleaning decision, in the order the pipeline made it.")

qa_lines <- c(
  sprintf("QA REPORT, SIMULATED Multimodal Ad Study (seed %s), made by prepare_data.R on %s", seed_txt, format(Sys.Date())),
  "SIMULATED DATA for teaching. No real person was recorded.", "",
  "1. Counts at each pipeline step (rows: the GSR metrics file through step 3, then the participant x stimulus table)",
  capture.output(print(as.data.frame(pipe %>% select(-order)), row.names = FALSE)), "",
  "2. Files read", capture.output(print(as.data.frame(inv %>% select(folder, file, kb, header_line, separator)), row.names = FALSE)), "",
  "3. Keys", sprintf("   Raw keys not matching the session log: %s", paste(unique(paste0(audit$file[!audit$exact_match], ": ", show_key(audit$raw[!audit$exact_match]))), collapse = "; ")),
  sprintf("   After UPPER(TRIM()) and the crosswalk: every file holds the same %d participants.", length(roster)),
  sprintf("   Duplicated keys: long table %d, wide table %d.", dups_long, dups_wide), "",
  "4. Ranges and missing values (codebook ranges)",
  capture.output(print(as.data.frame(qa %>% mutate(across(c(min, max), ~ round(.x, 2)))), row.names = FALSE)), "",
  "5. Consistency checks",
  sprintf("   Survey item means agree with SurveyStatistics.txt: yes. Student copy equals the raw statistics: yes (not used)."),
  sprintf("   Respondent ratio (%%) recomputed from the individual AOI file equals the aggregated export: yes."),
  sprintf("   Sensor Data versus exports (6 participants, 2 ads): Logo share mean absolute difference %.2f points (largest %.2f); Joy largest difference %.2f points.",
          mean(abs(cons$logo_diff)), max(abs(cons$logo_diff)), max(abs(cons$joy_diff))),
  sprintf("   Clocks: Sensor Data StartMedia minus Start (ms) is constant within participant (spread at most %.1f ms); annotation times count from the ad onset.",
          max(clock_sum$spread_ms)),
  sprintf("   Order of the ads from Start (ms) equals Group for %d of %d participants (the exception has Group = Default) and the session log for %d of %d.",
          n_order_ok, nrow(details), sum(details$order_log == details$order_from_data), nrow(details)), "",
  "6. Exclusions and missing data",
  sprintf("   Rule R1 dropped the aborted recording of P04. Rule R2 excluded %s. Rule R3 set GSR to missing for %s.",
          paste(rule$participant_id[rule$include == 0], collapse = " and "),
          paste(paste(gsr_t$participant_id[gsr_t$gsr_valid == 0], gsr_t$stimulus[gsr_t$gsr_valid == 0]), collapse = ", ")),
  sprintf("   Analysis sample: %d participants (%d rows in the long table); GSR analyses: %d rows.", n_incl, n_long_incl,
          sum(long$include == 1 & long$gsr_valid == 1)))
writeLines(qa_lines, "qa_report.txt")
cat("wrote qa_report.txt\n\n")

